SELECT     locations.type AS LocationType,     COUNT(bookings_anglers.id) AS CountOfRods,     COALESCE(SUM(catch_returns_returns.quantity), 0) AS TotalCatches,     CAST(ROUND(COALESCE(       SUM(catch_returns_returns.length * catch_returns_returns.quantity)         / NULLIF(SUM(catch_returns_returns.quantity), 0),       0     ), 0) AS INTEGER) AS AvgLength,     COALESCE(MAX(catch_returns_returns.length), 0) AS MaxLargeFish   FROM bookings   INNER JOIN locations ON locations.id = bookings.location_id   INNER JOIN bookings_anglers ON bookings_anglers._parent_id = bookings.id   LEFT JOIN catch_returns ON catch_returns.booking_id = bookings.id   AND catch_returns.return_completed = 1           LEFT JOIN catch_returns_returns ON catch_returns_returns._parent_id = catch_returns.id   WHERE DATE(bookings.date) >= DATE(?)     AND DATE(bookings.date) <= DATE(?)        GROUP BY locations.type